16	// grab SQL password from .env before anything else runs - it's gitignored so we're safe
17	DotEnvLoader.Load(Directory.GetCurrentDirectory());
18	
19	WebApplicationBuilder builder = WebApplication.CreateBuilder(args);
20	
21	builder.Services.AddControllers(options =>
22	{
23	    // validation errors use camelCase field names to match the JSON the client sent
24	    // otherwise you get "CourseCode" errors when you sent "courseCode" - super annoying
25	    options.ModelMetadataDetailsProviders.Add(new SystemTextJsonValidationMetadataProvider());
26	});
27	
28	builder.Services.AddOpenApi();
29	builder.Services.AddProblemDetails();
30	
31	// pick your poison: JSON file for local dev, SQL Server for real deployments
32	// service layer doesn't care which one - it just sees ICourseRepository
33	string dataSource = builder.Configuration["DataSource"] ?? DataSources.Json;
34	switch (dataSource)
35	{
36	    case DataSources.Json:
37	        // singleton because everyone shares one file - scoped would be chaos
38	        builder.Services.AddSingleton<ICourseRepository, JsonCourseRepository>();
39	        break;
40	
41	    case DataSources.SqlServer:
42	        // scoped on purpose: AddDbContext is scoped, so the repo using it has to be too.
43	        // singleton here = captive dependency (one DbContext stuck forever, not thread-safe).
44	        // json repo is the opposite, see docs/singleton-vs-scoped.md
45	        builder.Services.AddDbContext<GritTrackDbContext>(options =>
46	            options.UseSqlServer(SqlConnectionStringFactory.Build(builder.Configuration)));
47	        builder.Services.AddScoped<ICourseRepository, SqlCourseRepository>();
48	        break;
49	
50	    default:
51	        throw new InvalidOperationException(
52	            $"DataSource '{dataSource}' is invalid. Use '{DataSources.Json}' or '{DataSources.SqlServer}'.");
53	}
54	
55	builder.Services.AddScoped<ICourseService, CourseService>();
56	
57	// auth toggle: off = anyone can write (good for testing), on = need a token
58	// GETs are always public because grades aren't sensitive data (yet?)
59	builder.Services.Configure<AuthOptions>(builder.Configuration.GetSection(AuthOptions.SectionName));
60	AuthOptions authOptions = builder.Configuration.GetSection(AuthOptions.SectionName).Get<AuthOptions>() ?? new AuthOptions();
61	builder.Services.AddSingleton<IJwtTokenService, JwtTokenService>();
62	
63	if (authOptions.Enabled)
64	{
65	    // fail fast if secrets are missing - better than cryptic errors on first login
66	    ValidateAuthSettings(authOptions);
67	
68	    builder.Services
69	        .AddAuthentication(JwtBearerDefaults.AuthenticationScheme)
70	        .AddJwtBearer(options =>
71	        {
72	            options.TokenValidationParameters = new TokenValidationParameters
73	            {
74	                ValidateIssuer = true,
75	                ValidIssuer = authOptions.Issuer,
76	                ValidateAudience = true,
77	                ValidAudience = authOptions.Audience,
78	                ValidateLifetime = true,
79	                ValidateIssuerSigningKey = true,
80	                IssuerSigningKey = new SymmetricSecurityKey(Encoding.UTF8.GetBytes(authOptions.SigningKey!)),
81	                ClockSkew = TimeSpan.FromSeconds(30)
82	            };
83	        });
84	
85	    builder.Services.AddAuthorizationBuilder()
86	        .AddPolicy(AuthPolicies.WriteAccess, policy => policy.RequireAuthenticatedUser());
87	}
88	else
89	{
90	    // same policy name but auto-pass - controller code stays unchanged
91	    builder.Services.AddAuthorizationBuilder()
92	        .AddPolicy(AuthPolicies.WriteAccess, policy => policy.RequireAssertion(_ => true));
93	}
94	
95	WebApplication app = builder.Build();
96	
97	// auto-migrate on startup - no manual EF commands needed
98	if (dataSource == DataSources.SqlServer)
99	    await ApplyMigrationsAsync(app);
100	
101	// global exception handler - no try/catch spam in every action
102	app.UseExceptionHandler();
103	
104	if (app.Environment.IsDevelopment())
105	{
106	    app.MapOpenApi();
107	}
108	
109	app.UseHttpsRedirection();
110	
111	// 401 if you're missing a token on protected routes
112	if (authOptions.Enabled)
113	    app.UseAuthentication();
114	app.UseAuthorization();
115	
116	app.MapControllers();
117	
118	// log what mode we're running in - helps debug "why did this fail" issues
119	app.Logger.LogInformation("Data source: {DataSource}", dataSource);
120	app.Logger.LogInformation("Auth: {AuthState}", authOptions.Enabled ? "ON" : "OFF");
121	
122	app.Run();
