124	// yells at you if auth is on but you forgot to set the secrets
125	// use: dotnet user-secrets set "Auth:SigningKey" "something-long-and-random"
126	static void ValidateAuthSettings(AuthOptions authOptions)
127	{
128	    const int minimumSigningKeyLength = 32;
129	    List<string> problems = new List<string>();
130	
131	    if (string.IsNullOrWhiteSpace(authOptions.SigningKey) || authOptions.SigningKey.Length < minimumSigningKeyLength)
132	        problems.Add($"Auth:SigningKey is missing or shorter than {minimumSigningKeyLength} characters");
133	    if (string.IsNullOrWhiteSpace(authOptions.DemoPassword))
134	        problems.Add("Auth:DemoPassword is missing");
135	
136	    if (problems.Count == 0)
137	        return;
138	
139	    throw new InvalidOperationException(
140	        $"Auth:Enabled is true but {string.Join(" and ", problems)}. " +
141	        "Set them with: dotnet user-secrets set \"Auth:SigningKey\" \"<long random text>\" " +
142	        "and dotnet user-secrets set \"Auth:DemoPassword\" \"<your demo password>\" " +
143	        "(run from the GritTrack.Api folder), or set Auth:Enabled to false.");
144	}
