146	// applies EF migrations with retry - SQL Server containers lie about being ready
147	// (the retry rules live in DatabaseMigrationRunner so they can be tested)
148	static Task ApplyMigrationsAsync(WebApplication app)
149	    => DatabaseMigrationRunner.RunWithRetryAsync(async () =>
150	    {
151	        using IServiceScope scope = app.Services.CreateScope();
152	        GritTrackDbContext context = scope.ServiceProvider.GetRequiredService<GritTrackDbContext>();
153	        await context.Database.MigrateAsync();
154	    }, app.Logger);
