3	namespace GritTrack.Services.Api
4	{
5	    // sits in the HttpClient's pipeline and adds "Authorization: Bearer <token>"
6	    // to every request once you're signed in. reads (GET) still work without
7	    // it, because browsing is public. a write with no token goes out anyway:
8	    // the server answers 401 and the app sends the user to log in
9	    // (see AuthService.RunWriteAsync)
10	    public class BearerTokenHandler : DelegatingHandler
11	    {
12	        private readonly IAuthService _authService;
13	
14	        public BearerTokenHandler(IAuthService authService)
15	        {
16	            _authService = authService;
17	        }
18	
19	        protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request, CancellationToken cancellationToken)
20	        {
21	            var token = await _authService.GetTokenAsync();
22	            if (token is not null)
23	                request.Headers.Authorization = new AuthenticationHeaderValue("Bearer", token);
24	
25	            return await base.SendAsync(request, cancellationToken);
26	        }
27	    }
