protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request, CancellationToken cancellationToken)
{
    // only write methods need authorization - reads are public, so skip the token lookup entirely
    // (touching SecureStorage on every GET would be wasteful and break the "browsing is anonymous" design)
    bool isWriteMethod = request.Method == HttpMethod.Post
                      || request.Method == HttpMethod.Put
                      || request.Method == HttpMethod.Delete
                      || request.Method == HttpMethod.Patch;

    if (isWriteMethod)
    {
        string? token = await _authService.GetTokenAsync();
        if (token is not null)
            request.Headers.Authorization = new AuthenticationHeaderValue("Bearer", token);
    }

    return await base.SendAsync(request, cancellationToken);
}
